        ),
    ]
}

pub fn gen_seeds(dir: &str) -> Vec<String> {
    let mut lines = Vec::new();
    let _ = fs::create_dir_all(dir);

    let img1 = rgba_pattern_a(64, 48);
    let img2 = rgba_pattern_b(73, 55);

    let png1 = encode_png_bytes(&img1, 64, 48);
    let png2 = encode_png_bytes(&img2, 73, 55);
    let rich1_raw = encode_palette_png_with_features(&img1);
    let rich2_raw = encode_palette_png_with_features(&img2);
    let gray1 = encode_gray1_interlaced_png(&img1);
    let gray2 = encode_gray1_interlaced_png(&img2);
    let rgba16_1 = encode_rgba16_interlaced_png(&img1);
    let rgba16_2 = encode_rgba16_interlaced_png(&img2);

    let (decode32_a, decode32_b) = choose_distinct_nonempty_png_pair(
        gray1.clone(),
        rgba16_2.clone(),
        rich1_raw.clone(),
        png2.clone(),
    );
    let (decode24_a, decode24_b) = choose_distinct_nonempty_png_pair(
        rich2_raw.clone(),
        gray2.clone(),
        png1.clone(),
        rgba16_1.clone(),
    );
    let (inspect_a, inspect_b) = choose_distinct_nonempty_png_pair(
        rich1_raw.clone(),
        rgba16_1.clone(),
        gray1.clone(),
        png2.clone(),
    );

    for (op, idx, bytes) in [
        ("decode32_png", 1usize, &decode32_a),
        ("decode32_png", 2usize, &decode32_b),
        ("decode24_png", 1usize, &decode24_a),
        ("decode24_png", 2usize, &decode24_b),
        ("inspect_png", 1usize, &inspect_a),
        ("inspect_png", 2usize, &inspect_b),
    ] {
        let path = format!("{}/{}.{}.bin", dir, op, idx);
        let _ = fs::write(&path, bytes);
        lines.push(format!("seed {} {}", op, path));
    }

    let plain1 = synth_plaintext_a(24 * 1024);
    let plain2 = synth_plaintext_b(28 * 1024);
    let z1 = compress_zlib_bytes(&plain1);
    let z2 = compress_zlib_bytes(&plain2);

    for (idx, bytes) in [(1usize, &z1), (2usize, &z2)] {
        let path = format!("{}/zlib_decompress.{}.bin", dir, idx);
        let _ = fs::write(&path, bytes);
        lines.push(format!("seed zlib_decompress {}", path));
    }

    for (idx, bytes) in [(1usize, &plain1), (2usize, &plain2)] {
        let path = format!("{}/raw_deflate_inflate.{}.bin", dir, idx);
        let _ = fs::write(&path, bytes);
        lines.push(format!("seed raw_deflate_inflate {}", path));
    }

    let raw1 = raw_container(40, 30, &rgba_pattern_a(40, 30));
    let raw2 = raw_container(57, 41, &rgba_pattern_b(57, 41));
    for op in ["encode_png", "color_convert", "file_codec", "memory_codec"] {
        for (idx, bytes) in [(1usize, &raw1), (2usize, &raw2)] {
            let path = format!("{}/{}.{}.bin", dir, op, idx);
            let _ = fs::write(&path, bytes);
            lines.push(format!("seed {} {}", op, path));
        }
    }

    let chunk1 = if !png1.is_empty() {
        png1.clone()
    } else {
        decode32_a.clone()
    };
    let chunk2 = if !inspect_b.is_empty() && inspect_b != chunk1 {
        inspect_b.clone()
    } else if !png2.is_empty() && png2 != chunk1 {
        png2.clone()
    } else {
        decode32_b.clone()
    };
    for (idx, bytes) in [(1usize, &chunk1), (2usize, &chunk2)] {
        let path = format!("{}/chunk_ops.{}.bin", dir, idx);
        let _ = fs::write(&path, bytes);
        lines.push(format!("seed chunk_ops {}", path));
    }

    let sp1 = synth_plaintext_a(1024);
    let sp2 = synth_plaintext_b(1536);
    for (idx, bytes) in [(1usize, &sp1), (2usize, &sp2)] {
        let path = format!("{}/stateful_palette_encode.{}.bin", dir, idx);
        let _ = fs::write(&path, bytes);
        lines.push(format!("seed stateful_palette_encode {}", path));
    }

    lines
}

fn encode_gray1_interlaced_png_large(seed: &[u8], w: u32, h: u32) -> Vec<u8> {
    unsafe {
        let mut st = MaybeUninit::<LodePNGState>::zeroed();
        lodepng_state_init(st.as_mut_ptr());
        let stp = st.as_mut_ptr();

        (*stp).info_raw = lodepng_color_mode_make(0 as _, 1);
        (*stp).info_png.color = lodepng_color_mode_make(0 as _, 1);
        (*stp).info_png.interlace_method = 1;
        (*stp).encoder.auto_convert = 0;

        let rowbytes = ((w + 7) / 8) as usize;
        let mut image = vec![0u8; rowbytes.saturating_mul(h as usize)];

        for y in 0..h as usize {
            for x in 0..w as usize {
                let s = if seed.is_empty() {
                    ((x as u32 * 13 + y as u32 * 7) & 255) as u8
                } else {
                    seed[(x.wrapping_mul(17).wrapping_add(y * rowbytes)) % seed.len()]
                };
                let bit = ((s.rotate_left((x & 7) as u32) ^ (y as u8).wrapping_mul(11)) >> 5) & 1;
                if bit != 0 {
                    let idx = y * rowbytes + x / 8;
                    image[idx] |= 1u8 << (7 - (x & 7));
                }
            }
        }

        let mut out_ptr: *mut c_uchar = ptr::null_mut();
        let mut out_size: size_t = 0;
        let err = lodepng_encode(
            &mut out_ptr,
            &mut out_size,
            image.as_ptr(),
            w as c_uint,
            h as c_uint,
            stp,
        );

        let out = if err == 0 && !out_ptr.is_null() {
            let v = std::slice::from_raw_parts(out_ptr, out_size as usize).to_vec();
            free_c_buffer(out_ptr);
            v
        } else {
            free_c_buffer(out_ptr);
            Vec::new()
        };

        lodepng_state_cleanup(stp);
        out
    }
}

fn encode_rgba16_interlaced_png_large(seed: &[u8], w: u32, h: u32) -> Vec<u8> {
    unsafe {
        let mut st = MaybeUninit::<LodePNGState>::zeroed();
        lodepng_state_init(st.as_mut_ptr());
        let stp = st.as_mut_ptr();

        (*stp).info_raw = lodepng_color_mode_make(6 as _, 16);
        (*stp).info_png.color = lodepng_color_mode_make(6 as _, 16);
        (*stp).info_png.interlace_method = 1;
        (*stp).encoder.auto_convert = 0;

        let mut image = vec![0u8; (w as usize).saturating_mul(h as usize).saturating_mul(8)];

        for y in 0..h {
            for x in 0..w {
                let i = ((y * w + x) as usize) * 8;
                let s0 = if seed.is_empty() {
                    (x.wrapping_mul(9) ^ y.wrapping_mul(13)) as u8
                } else {
                    seed[(i + 0) % seed.len()]
                };
                let s1 = if seed.is_empty() {
                    (x.wrapping_mul(5) + y.wrapping_mul(7)) as u8
                } else {
                    seed[(i + 1) % seed.len()]
                };
                let s2 = if seed.is_empty() {
                    (x.wrapping_mul(17) + y.wrapping_mul(3)) as u8
                } else {
                    seed[(i + 2) % seed.len()]
                };
                let s3 = if seed.is_empty() {
                    (x ^ y) as u8
                } else {
                    seed[(i + 3) % seed.len()]
                };
                let r = (((s0 as u16) << 8) | (s1 as u16)).to_be_bytes();
                let g = ((((s1 ^ 0x5a) as u16) << 8) | (s2 as u16)).to_be_bytes();
                let b = ((((s2 ^ 0xa5) as u16) << 8) | (s3 as u16)).to_be_bytes();
                let a = (((255u16.wrapping_sub(s3 as u16)) << 8) | (s0 as u16)).to_be_bytes();
                image[i..i + 2].copy_from_slice(&r);
                image[i + 2..i + 4].copy_from_slice(&g);
                image[i + 4..i + 6].copy_from_slice(&b);
                image[i + 6..i + 8].copy_from_slice(&a);
            }
        }

        let mut out_ptr: *mut c_uchar = ptr::null_mut();
        let mut out_size: size_t = 0;
        let err = lodepng_encode(
            &mut out_ptr,
            &mut out_size,
            image.as_ptr(),
            w as c_uint,
            h as c_uint,
            stp,
        );

        let out = if err == 0 && !out_ptr.is_null() {
            let v = std::slice::from_raw_parts(out_ptr, out_size as usize).to_vec();
            free_c_buffer(out_ptr);
            v
        } else {
            free_c_buffer(out_ptr);
            Vec::new()
        };

        lodepng_state_cleanup(stp);
        out
    }
}

fn encode_palette_png_with_many_chunks(seed: &[u8], w: u32, h: u32) -> Vec<u8> {
    unsafe {
        let mut st = MaybeUninit::<LodePNGState>::zeroed();
        lodepng_state_init(st.as_mut_ptr());
        let stp = st.as_mut_ptr();

        (*stp).info_raw = lodepng_color_mode_make(3 as _, 8);
        (*stp).info_png.color = lodepng_color_mode_make(3 as _, 8);
        (*stp).info_png.interlace_method = 1;
        (*stp).encoder.auto_convert = 0;
        (*stp).encoder.force_palette = 1;
        (*stp).encoder.text_compression = 1;

        for i in 0..64u8 {
            let r = i.wrapping_mul(37).wrapping_add(11);
            let g = i.wrapping_mul(19).wrapping_add(23);
            let b = i.wrapping_mul(53).wrapping_add(7);
            let a = if i % 7 == 0 { 96 } else { 255 };
            let _ = lodepng_palette_add(&mut (*stp).info_raw, r, g, b, a);
            let _ = lodepng_palette_add(&mut (*stp).info_png.color, r, g, b, a);
        }

        let text_payload_a = synth_plaintext_a(256 * 1024);
        let text_payload_b = synth_plaintext_b(256 * 1024);

        for i in 0..48usize {
            let key = match CString::new(format!("Comment{:02}", i)) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let start = (i * 4093) % text_payload_a.len();
            let end = (start + 2048).min(text_payload_a.len());
            let mut val = text_payload_a[start..end].to_vec();
            if val.is_empty() {
                val.extend_from_slice(b"x");
            }
            let val = match CString::new(val) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let _ = lodepng_add_text(&mut (*stp).info_png, key.as_ptr(), val.as_ptr());
        }

        for i in 0..48usize {
            let key = match CString::new(format!("IComment{:02}", i)) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let lang = b"en\0";
            let trans = match CString::new(format!("translation{:02}", i)) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let start = (i * 8111) % text_payload_b.len();
            let end = (start + 2048).min(text_payload_b.len());
            let mut val = text_payload_b[start..end].to_vec();
            if val.is_empty() {
                val.extend_from_slice(b"y");
            }
            let val = match CString::new(val) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let _ = lodepng_add_itext(
                &mut (*stp).info_png,
                key.as_ptr(),
                lang.as_ptr() as *const c_char,
                trans.as_ptr(),
                val.as_ptr(),
            );
        }

        let icc_name = b"sRGB\0";
        let mut icc_profile = synth_plaintext_a(32 * 1024);
        if icc_profile.is_empty() {
            icc_profile.push(b'Z');
        }
        let exif_blob = {
            let mut v = vec![0x4d, 0x4d, 0x00, 0x2a, 0, 0, 0, 8, 0, 1, 0x01, 0x12, 0, 3, 0, 0, 0, 1, 0, 1];
            v.extend_from_slice(&synth_plaintext_b(8 * 1024));
            v
        };

        let _ = lodepng_set_icc(
            &mut (*stp).info_png,
            icc_name.as_ptr() as *const c_char,
            icc_profile.as_ptr(),
            icc_profile.len() as c_uint,
        );
        let _ = lodepng_set_exif(
            &mut (*stp).info_png,
            exif_blob.as_ptr(),
            exif_blob.len() as c_uint,
        );

        let mut image = vec![0u8; (w as usize).saturating_mul(h as usize)];
        for (i, px) in image.iter_mut().enumerate() {
            let b = if seed.is_empty() {
                i as u8
            } else {
                seed[(i.wrapping_mul(131)) % seed.len()]
            };
            *px = b & 63;
        }

        let mut out_ptr: *mut c_uchar = ptr::null_mut();
        let mut out_size: size_t = 0;
        let err = lodepng_encode(
            &mut out_ptr,
            &mut out_size,
            image.as_ptr(),
            w as c_uint,
            h as c_uint,
            stp,
        );

        let out = if err == 0 && !out_ptr.is_null() {
            let v = std::slice::from_raw_parts(out_ptr, out_size as usize).to_vec();
            free_c_buffer(out_ptr);
            v
        } else {
            free_c_buffer(out_ptr);
            Vec::new()
        };

        lodepng_state_cleanup(stp);
        out
    }
}

pub fn gen_perf(dir: &str) -> Vec<String> {
    let mut lines = Vec::new();
    let _ = fs::create_dir_all(dir);

    let w = 1536u32;
    let h = 1536u32;
    let big_rgba = rgba_pattern_b(w, h);

    let big_png = encode_png_bytes(&big_rgba, w, h);

    let big_decode32 = {
        let p = encode_rgba16_interlaced_png_large(&big_rgba, 1024, 1024);
        if p.is_empty() { big_png.clone() } else { p }
    };

    let big_decode24 = {
        let p = encode_gray1_interlaced_png_large(&big_rgba, 2048, 1536);
        if p.is_empty() { big_png.clone() } else { p }
    };

    let big_chunky_png = {
        let p = encode_palette_png_with_many_chunks(&big_rgba, 1024, 1024);
        if !p.is_empty() {
            p
        } else {
            let q = encode_palette_png_with_features(&big_rgba);
            if !q.is_empty() { q } else { big_png.clone() }
        }
    };

    for (op, bytes) in [
        ("decode32_png", &big_decode32),
        ("decode24_png", &big_decode24),
        ("inspect_png", &big_chunky_png),
    ] {
        let path = format!("{}/{}.perf.bin", dir, op);
        let _ = fs::write(&path, bytes);
        lines.push(format!("perf {} {}", op, path));
    }

    let big_raw = raw_container(w, h, &big_rgba);
    for op in ["encode_png", "color_convert", "file_codec", "memory_codec"] {
        let path = format!("{}/{}.perf.bin", dir, op);
        let _ = fs::write(&path, &big_raw);
        lines.push(format!("perf {} {}", op, path));
    }

    let big_plain = synth_plaintext_b(8 * 1024 * 1024);
    let big_z = compress_zlib_bytes(&big_plain);

    let path = format!("{}/zlib_decompress.perf.bin", dir);
    let _ = fs::write(&path, &big_z);
    lines.push(format!("perf zlib_decompress {}", path));

    let path = format!("{}/raw_deflate_inflate.perf.bin", dir);
    let _ = fs::write(&path, &big_plain);
    lines.push(format!("perf raw_deflate_inflate {}", path));

    let stateful_seed = synth_plaintext_b(2 * 1024 * 1024);
    let path = format!("{}/stateful_palette_encode.perf.bin", dir);
    let _ = fs::write(&path, &stateful_seed);
    lines.push(format!("perf stateful_palette_encode {}", path));

    let path = format!("{}/chunk_ops.perf.bin", dir);
    let _ = fs::write(&path, &big_chunky_png);
    lines.push(format!("perf chunk_ops {}", path));

    lines
}
